const SLANG = [
// ── INTERNET / GEN-Z ──
{id:1,word:"GOAT",meaning:"Greatest Of All Time — used to describe someone who is the absolute best in their field.",amharic:"ምርጡ / ካሁን ሁሉ የሚበልጥ",example:"Michael Jordan is the GOAT — nobody debates that in basketball.",origin:"internet"},
{id:2,word:"Slay",meaning:"To do something incredibly well; to look amazing; to absolutely dominate.",amharic:"በሚያስደንቅ ሁኔታ ማድረግ",example:"Did you see her presentation? She absolutely slayed it from beginning to end.",origin:"genz"},
{id:3,word:"Lowkey",meaning:"Secretly; to a small degree; without drawing attention; understated.",amharic:"ሳይናቱ / ትንሽ",example:"I'm lowkey obsessed with that new album but I don't want to admit it.",origin:"internet"},
{id:4,word:"Highkey",meaning:"Openly; obviously; to a high degree; the opposite of lowkey.",amharic:"ሙሉ በሙሉ / ግልጽ ሆኖ",example:"I am highkey in love with this city — the food, the culture, everything is perfect.",origin:"internet"},
{id:5,word:"Vibe",meaning:"A feeling, atmosphere, or energy that a person or place gives off.",amharic:"ስሜት / ድባብ",example:"This coffee shop has such a relaxed vibe — I could work here for hours.",origin:"internet"},
{id:6,word:"Fire",meaning:"Excellent, amazing, or very impressive — used for music, food, clothes, etc.",amharic:"ድንቅ / ጥሩ",example:"Have you heard her new song? It is absolutely fire from start to finish.",origin:"us"},
{id:7,word:"Lit",meaning:"Exciting, amazing, or extremely fun; also drunk or intoxicated.",amharic:"ደስ የሚያሰኝ / ጥሩ",example:"The party last night was completely lit — everyone was dancing until sunrise.",origin:"us"},
{id:8,word:"Bussin",meaning:"Extremely good, especially used for food that tastes amazing.",amharic:"ጣፋጭ / ደስ የሚያሰኝ",example:"My grandmother's injera is absolutely bussin — no restaurant comes close.",origin:"us"},
{id:9,word:"No cap",meaning:"No lie; seriously; I'm telling the truth, this really happened.",amharic:"ሐሰት ሳይሆን / እውነት ነው",example:"No cap, that was the best meal I have ever eaten in my entire life.",origin:"us"},
{id:10,word:"Cap",meaning:"A lie; to lie or exaggerate; the opposite of 'no cap'.",amharic:"ሐሰት / ውሸት",example:"He says he ran a marathon in two hours — that's total cap, nobody believes him.",origin:"us"},
{id:11,word:"Flex",meaning:"To show off possessions, achievements, or status, often in a boastful way.",amharic:"ጉራ ማድረግ / ማሳየት",example:"He's always flexing his new designer shoes on every social media post.",origin:"us"},
{id:12,word:"Drip",meaning:"A very stylish, impressive, and fashionable sense of clothing and accessories.",amharic:"ፋሽን / ቆንጆ ልብስ",example:"She walked in with serious drip — head to toe designer from Paris.",origin:"us"},
{id:13,word:"Clout",meaning:"Social influence, fame, or power, especially on social media platforms.",amharic:"ዝና / ተጽዕኖ",example:"She gained massive clout after her viral video reached 50 million views.",origin:"internet"},
{id:14,word:"Ghosting",meaning:"Suddenly cutting off all communication with someone without any explanation.",amharic:"ሳይነግሩ መጥፋት",example:"After three great dates, he completely ghosted her — never replied to another message.",origin:"internet"},
{id:15,word:"Stan",meaning:"An obsessive fan; to be an extremely devoted supporter of someone.",amharic:"ሞቅ ያለ ደጋፊ",example:"I am a hardcore stan of Beyoncé — I have attended every concert on every world tour.",origin:"internet"},
{id:16,word:"Cancel",meaning:"To withdraw support from a public figure after they do something offensive.",amharic:"ድጋፍ ማስወጣት",example:"The actor was completely cancelled after his deeply offensive tweets resurfaced online.",origin:"internet"},
{id:17,word:"Woke",meaning:"Alert to social injustice and racial inequality; socially and politically aware.",amharic:"ማህበራዊ ፍትህ ያስጨነቀው",example:"She writes about being woke and using your privilege to advocate for others.",origin:"us"},
{id:18,word:"Savage",meaning:"Someone who is fearlessly bold or impressively harsh and direct.",amharic:"ቀጥተኛ / ጀግና",example:"She responded to his rude comment with a savage one-liner that shut everyone up.",origin:"us"},
{id:19,word:"Shook",meaning:"Deeply shocked, surprised, or emotionally overwhelmed by something.",amharic:"ደንግጦ / ተደምሞ",example:"I am absolutely shook — I got into my dream university on the first attempt.",origin:"internet"},
{id:20,word:"Snatched",meaning:"Looking extremely attractive, usually referring to having a great body or outfit.",amharic:"ቆንጆ ሆኖ / ዝጋጁ",example:"After months of training, she walked into the event looking completely snatched.",origin:"genz"},
{id:21,word:"Bet",meaning:"Okay, sounds good; agreement or confirmation that something will happen.",amharic:"እሺ / ሆኖ ይሂድ",example:"Can you pick me up at 7? Bet, I'll be there exactly on time.",origin:"us"},
{id:22,word:"Salty",meaning:"Upset, bitter, or irritated about something, usually a minor disappointment.",amharic:"ቅር ያለው / ተናዶ",example:"He's been salty all day because he lost the video game by just one point.",origin:"us"},
{id:23,word:"Extra",meaning:"Over-the-top, excessive, or unnecessarily dramatic in behavior.",amharic:"ከሚፈለገው ይበልጥ",example:"She sent 50 messages after not getting a reply within five minutes — so extra.",origin:"us"},
{id:24,word:"Thirsty",meaning:"Desperately seeking attention, affection, or validation from others.",amharic:"ፍቅር የሚሻ / ትኩረት የሚፈልግ",example:"He likes every single one of her posts within seconds of posting — so thirsty.",origin:"us"},
{id:25,word:"Shade",meaning:"Disrespect or a subtle insult directed at someone, often indirect.",amharic:"ስውር ስድብ / አሽሙር",example:"Her comment about people who don't read was obvious shade aimed at her ex.",origin:"us"},
{id:26,word:"Tea",meaning:"Gossip, juicy secrets, or the latest interesting news about someone.",amharic:"ምስጢር / ወሬ",example:"Spill the tea — what exactly happened between them at the party?",origin:"us"},
{id:27,word:"Dope",meaning:"Excellent, cool, or very impressive — a versatile term of strong approval.",amharic:"ጥሩ / ቀዳሚ",example:"That documentary about climate change is genuinely dope — you have to watch it.",origin:"us"},
{id:28,word:"FOMO",meaning:"Fear Of Missing Out — anxiety that others are having exciting experiences without you.",amharic:"ሳትሳተፍ የሚሰማ ፍርሃት",example:"I had serious FOMO watching everyone's festival photos while I was stuck at work.",origin:"internet"},
{id:29,word:"YOLO",meaning:"You Only Live Once — used to justify impulsive or adventurous behavior.",amharic:"አንዴ ብቻ ነው የምትኖረው",example:"I quit my boring office job and traveled the world for a year — YOLO!",origin:"internet"},
{id:30,word:"Periodt",meaning:"Used to emphasize a final, definitive statement — means 'end of discussion'.",amharic:"ቁርጥ ነው / ሌላ ሐሳብ የለም",example:"She is the most talented artist of this generation, periodt — not up for debate.",origin:"genz"},
{id:31,word:"Rizz",meaning:"Natural charm, charisma, or the ability to attract others effortlessly.",amharic:"ማግለጥ / ማራኪነት",example:"He has unmatched rizz — he walked in and every person in the room noticed him.",origin:"genz"},
{id:32,word:"NPC",meaning:"A person who acts without independent thought, like a non-player character in a video game.",amharic:"ሳያስብ ተልዕኮ የሚፈጽም",example:"Stop being an NPC — think for yourself and don't just follow what everyone else does.",origin:"genz"},
{id:33,word:"Delulu",meaning:"Delusional — having unrealistic, wildly optimistic, or out-of-touch beliefs.",amharic:"ሐሳብ ያበደ / ተጨባጭ ያልሆነ",example:"You think he'll propose after one date? Bestie, you are completely delulu.",origin:"genz"},
{id:34,word:"Era",meaning:"A phase or current stage of your life — 'I'm in my healing era', etc.",amharic:"ወቅቴ / ደረጃ",example:"I'm fully in my self-improvement era — gym every day, reading every night.",origin:"genz"},
{id:35,word:"Hits different",meaning:"Affects you in a deeper or more profound way than usual; strikes an unusual emotion.",amharic:"ለየት ያለ ስሜት ያስችላል",example:"Listening to this old playlist at midnight just hits different in a way I can't explain.",origin:"genz"},
{id:36,word:"It's giving",meaning:"It reminds you of something; it has a certain vibe, quality, or energy.",amharic:"የሚስጠው ስሜት",example:"That outfit is giving old Hollywood glamour — absolutely love the aesthetic.",origin:"genz"},
{id:37,word:"Understood the assignment",meaning:"Performed exceptionally well; did exactly what was expected and more.",amharic:"ትዕዛዙን ጠንቅቆ ተረዳ",example:"She wore the most perfectly themed costume — she completely understood the assignment.",origin:"genz"},
{id:38,word:"Main character",meaning:"Acting or feeling like the central protagonist of your own life story.",amharic:"ዋና ገጸ-ባሕርይ",example:"She walked through the city with main character energy — confident, stylish, purposeful.",origin:"genz"},
{id:39,word:"Rent free",meaning:"Something or someone that occupies your thoughts constantly without your permission.",amharic:"ሳይፈቀድ ሐሳብህ ውስጥ ያለ",example:"That argument is living rent free in my head and I cannot stop thinking about it.",origin:"genz"},
{id:40,word:"Villain arc",meaning:"A phase where someone starts acting selfishly or doing whatever they want without apology.",amharic:"ጎጂ ወቅት / ራሴ ለራሴ",example:"After being so nice my whole life, I'm entering my villain arc — no more people-pleasing.",origin:"genz"},
{id:41,word:"Glow up",meaning:"A dramatic positive transformation in appearance, confidence, or success.",amharic:"ዝቅ ብሎ ወጥቶ ድንቅ ሆኖ",example:"Her glow up from high school to college was completely unrecognizable — stunning.",origin:"genz"},
{id:42,word:"Down bad",meaning:"Deeply infatuated, heartbroken, or in a desperate state over someone you like.",amharic:"ጥልቅ ፍቅር ውስጥ / ሰቆቃ ውስጥ",example:"He texted her 'good morning' every day for a month without a reply — he is down bad.",origin:"genz"},
{id:43,word:"Red flag",meaning:"A warning sign that a person or situation is problematic or potentially harmful.",amharic:"አደጋ ምልክት",example:"He lied about small things from day one — that's a major red flag I should have noticed.",origin:"genz"},
{id:44,word:"Green flag",meaning:"A positive sign indicating that a person is healthy, trustworthy, or suitable.",amharic:"ጥሩ ምልክት",example:"He remembered her order without being asked a second time — that's a green flag.",origin:"genz"},
{id:45,word:"Ick",meaning:"A sudden feeling of disgust or attraction-killing aversion toward someone.",amharic:"ድንገት ተጸዳፊ ስሜት",example:"He started chewing loudly at dinner and I immediately got the ick — it was over.",origin:"genz"},
{id:46,word:"Soft life",meaning:"A lifestyle focused on comfort, ease, luxury, and avoiding unnecessary struggle.",amharic:"ቀሊሎ / ምቹ ሕይወት",example:"After years of hustle culture, she chose the soft life and never looked back.",origin:"genz"},
{id:47,word:"Core memory",meaning:"An unforgettable experience that becomes a fundamental part of who you are.",amharic:"ሕይወቱ ያጠናቀቀ ትዝታ",example:"That road trip with my best friends became an instant core memory I'll never forget.",origin:"genz"},
{id:48,word:"Touch grass",meaning:"To go outside and reconnect with the real world instead of spending all time online.",amharic:"ወደ ውጪ ሂድ / ከበይ ምንጨት ወጣ",example:"You have been online for 14 hours straight — please go touch grass immediately.",origin:"internet"},
{id:49,word:"Chronically online",meaning:"Spending so much time online that it distorts your sense of what is normal in real life.",amharic:"ዘወትር ኦንላይን ያለ",example:"His jokes made no sense to anyone because he is chronically online and out of touch.",origin:"internet"},
{id:50,word:"Simp",meaning:"Someone who gives excessive attention or does too much for someone they like.",amharic:"ሳይፈለጉ ዝቅ ብሎ ተቀባይ",example:"He drove four hours just to bring her lunch — absolute simp behavior.",origin:"internet"},
// ── AMERICAN SLANG ──
{id:51,word:"Chill",meaning:"Relaxed, calm, or easygoing; also to relax or hang out casually.",amharic:"ዘና ማለት / ዘና ያለ",example:"After the stressful week, we just chilled at home and watched movies all weekend.",origin:"us"},
{id:52,word:"Hang out",meaning:"To spend time with someone in a relaxed, informal setting.",amharic:"አብሮ ጊዜ ማሳለፍ",example:"Do you want to hang out this Saturday? We could grab food and walk around the market.",origin:"us"},
{id:53,word:"Bail",meaning:"To suddenly cancel plans or leave a situation unexpectedly.",amharic:"ሳይነግሩ መሄድ / ቃል ሰብሮ",example:"He bailed on us at the last minute again — this is becoming a habit.",origin:"us"},
{id:54,word:"Straight up",meaning:"Honestly, frankly, or truthfully — used to emphasize truthfulness.",amharic:"ቀጥ ብሎ / እውነቱን",example:"Straight up, that movie was disappointing and I expected so much better.",origin:"us"},
{id:55,word:"Y'all",meaning:"You all — a plural form of 'you' common in Southern American English.",amharic:"ሁላቸሁም / ሁሉም",example:"Y'all need to stop arguing and help me move these boxes right now.",origin:"us"},
{id:56,word:"Gonna",meaning:"Informal contraction of 'going to' — indicates future intention.",amharic:"የምሄደው / ያደርጋለሁ",example:"I'm gonna finish this project tonight no matter how long it takes.",origin:"us"},
{id:57,word:"Legit",meaning:"Legitimate, genuine, or truly impressive — can also mean 'honestly'.",amharic:"እውነትን / ሐቀኛ",example:"This is legit the best coffee shop I have ever been to — everything is perfect.",origin:"us"},
{id:58,word:"Awesome",meaning:"Extremely impressive, outstanding, or excellent.",amharic:"አስደናቂ / ምርጥ",example:"You passed your English exam on the first try? That is truly awesome!",origin:"us"},
{id:59,word:"Sketchy",meaning:"Seeming suspicious, unsafe, or untrustworthy.",amharic:"አጠራጣሪ / አደጋ ያለ",example:"That stranger offering free rides in the middle of the night seems incredibly sketchy.",origin:"us"},
{id:60,word:"Epic",meaning:"Impressively grand, heroic, or on a massive scale; extremely impressive.",amharic:"ታሪካዊ / አስደናቂ",example:"The finale of that series was absolutely epic — I cried for 20 minutes straight.",origin:"us"},
{id:61,word:"Gnarly",meaning:"Difficult, dangerous, or unpleasant; also used positively to mean very impressive.",amharic:"ከባድ / አስቸጋሪ",example:"That wave looked absolutely gnarly — I can't believe the surfer rode it so gracefully.",origin:"us"},
{id:62,word:"Bummed",meaning:"Feeling disappointed or sad about something that happened.",amharic:"ተስፋ ቆርጦ / ቅር ብሎ",example:"I'm really bummed that the concert got cancelled — I had been looking forward to it for months.",origin:"us"},
{id:63,word:"Stoked",meaning:"Extremely excited and enthusiastic about something.",amharic:"ደስ ብሎ / ጉጉ ሆኖ",example:"I'm so stoked for the camping trip this weekend — I've been packing all week.",origin:"us"},
{id:64,word:"Freak out",meaning:"To become extremely panicked, stressed, or emotionally overwhelmed.",amharic:"ደንበርት ማለት / ፍርሃት ውስጥ መግባት",example:"Please don't freak out, but I accidentally broke your favorite mug this morning.",origin:"us"},
{id:65,word:"Spill",meaning:"To reveal gossip, secrets, or information — often 'spill the tea'.",amharic:"ምስጢር መናገር / ወሬ ማውጣት",example:"Everyone gathered around the table demanding she spill every detail of the date.",origin:"us"},
{id:66,word:"Beef",meaning:"A conflict, ongoing argument, or feud between people or groups.",amharic:"ሽኩቻ / ጠብ",example:"Those two rappers have had serious beef since the award show incident last year.",origin:"us"},
{id:67,word:"Shady",meaning:"Dishonest, suspicious, or acting in an untrustworthy way.",amharic:"አጠራጣሪ / ሐሰተኛ",example:"That deal sounds extremely shady — I wouldn't sign anything without a lawyer present.",origin:"us"},
{id:68,word:"Bounce",meaning:"To leave quickly; to depart suddenly from a place.",amharic:"ፈጠን ብሎ መሄድ",example:"This party is boring — let's bounce and find somewhere more exciting.",origin:"us"},
{id:69,word:"Hella",meaning:"Very, extremely, or a lot — used as an intensifier (mainly West Coast US).",amharic:"በጣም / ከፍ ብሎ",example:"It's hella hot outside today — I refuse to leave the air-conditioned office.",origin:"us"},
{id:70,word:"Clap back",meaning:"To respond to criticism or an insult quickly and sharply.",amharic:"ፈጠን ብሎ ዝምብሎ",example:"She clappped back at the rude comment with a single witty sentence that ended the argument.",origin:"us"},
{id:71,word:"Wrecked",meaning:"Exhausted; completely destroyed emotionally or physically.",amharic:"ተዳክሞ / ሙሉ ለሙሉ ደክሞ",example:"After moving houses all weekend, I am absolutely wrecked and need three days of sleep.",origin:"us"},
{id:72,word:"Blew up",meaning:"Became suddenly and explosively famous or popular.",amharic:"ድንገት ዝነኛ ሆነ",example:"Her cooking videos blew up overnight — she had 5 million subscribers within a week.",origin:"us"},
{id:73,word:"Basic",meaning:"Mainstream, unremarkable, or conformist in tastes and preferences.",amharic:"ተራ / ያልጣለ",example:"Pumpkin spice latte and fall boots — he always jokes that her taste is basic.",origin:"us"},
{id:74,word:"Bougie",meaning:"Aspiring to or pretending to be upper class; pretentious.",amharic:"ሚዛናዊ ያልሆነ ቅንጦት",example:"She refuses to fly economy class — always a bit too bougie for the rest of us.",origin:"us"},
{id:75,word:"OG",meaning:"Original Gangster — someone original, respected, or among the first to do something.",amharic:"ዋናው / የቀደመ",example:"She's an OG in the tech industry — she coded her first app back in 1998.",origin:"us"},
// ── BRITISH SLANG ──
{id:76,word:"Bloke",meaning:"A man; a regular, ordinary guy (British equivalent of 'dude' or 'guy').",amharic:"ሰው / ወንድ",example:"Some bloke at the pub started telling the most incredible story I've ever heard.",origin:"uk"},
{id:77,word:"Mate",meaning:"A close friend or buddy — used very broadly in British English.",amharic:"ጓደኛ / ባልደረባ",example:"Alright mate, shall we grab a quick pint after work this evening?",origin:"uk"},
{id:78,word:"Cheeky",meaning:"Slightly disrespectful but in a funny or endearing way; boldly impudent.",amharic:"ሀፍረተ-ቢስ / ዘፈቀደ",example:"Go on, have a cheeky biscuit with your tea — you've earned it after that meeting.",origin:"uk"},
{id:79,word:"Dodgy",meaning:"Suspicious, unreliable, or of dubious quality; potentially dishonest.",amharic:"አጠራጣሪ / አስተማማኝ ያልሆነ",example:"That market stall looks a bit dodgy — I wouldn't buy electronics from there.",origin:"uk"},
{id:80,word:"Gutted",meaning:"Extremely disappointed or devastated about something.",amharic:"ቅር ብሎ / ሐዘን ተጠናወቶ",example:"I'm absolutely gutted we didn't get tickets — I've wanted to see that band for years.",origin:"uk"},
{id:81,word:"Chuffed",meaning:"Very pleased or delighted about something.",amharic:"ደስ ብሎ / ተኮርቶ",example:"She was absolutely chuffed when her essay received the highest mark in the entire class.",origin:"uk"},
{id:82,word:"Knackered",meaning:"Extremely tired or exhausted.",amharic:"ደክሞ / ሙሉ ለሙሉ ሰልችቶ",example:"After a double shift at the hospital, I am completely knackered and going straight to bed.",origin:"uk"},
{id:83,word:"Gobsmacked",meaning:"Utterly astonished; so surprised you cannot speak.",amharic:"አፉ ተዘግቶ / ተደናግጦ",example:"I was absolutely gobsmacked when she announced she was leaving to start her own company.",origin:"uk"},
{id:84,word:"Brilliant",meaning:"Excellent, wonderful, or very impressive — a very common British exclamation.",amharic:"ድንቅ / ዉብ",example:"That film was absolutely brilliant — I haven't been moved by a story like that in years.",origin:"uk"},
{id:85,word:"Rubbish",meaning:"Nonsense, terrible, or of very poor quality; also literally garbage.",amharic:"ቆሻሻ / ዋጋ ቢስ",example:"That film was complete rubbish — I fell asleep twice and demanded a refund.",origin:"uk"},
{id:86,word:"Ta",meaning:"Thank you — an informal and very casual British expression of gratitude.",amharic:"አመሰግናለሁ (ቀላሉ ቅጽ)",example:"Could you pass the sugar? Ta very much — you're a lifesaver.",origin:"uk"},
{id:87,word:"Sorted",meaning:"Arranged, fixed, settled, or taken care of successfully.",amharic:"ተስተካክሏል / ተጠናቅቋል",example:"Don't worry about the transport — I've already sorted it all out for the whole group.",origin:"uk"},
{id:88,word:"Minted",meaning:"Very wealthy; having a large amount of money.",amharic:"ብዙ ገንዘብ ያለ",example:"His family has been minted for generations — they own half the buildings in the city.",origin:"uk"},
{id:89,word:"Skint",meaning:"Having very little or no money; broke.",amharic:"ገንዘብ ያጣ / ጠፍቶ",example:"I'm completely skint until payday on Friday — can you lend me a tenner?",origin:"uk"},
{id:90,word:"Taking the piss",meaning:"Making fun of someone or treating something as a joke; being disrespectful.",amharic:"ቀልድ ሲወሰድ / ሞኝ ቆጥሮ",example:"He said I should work for free? He's got to be taking the piss — absolutely not.",origin:"uk"},
{id:91,word:"Faffing",meaning:"Wasting time doing things in a disorganized or ineffective way.",amharic:"ጊዜ ማባከን / ዘፈቀደ ማድረግ",example:"Stop faffing about and get your bag packed — we're leaving in ten minutes!",origin:"uk"},
{id:92,word:"Blag",meaning:"To obtain something through persuasion or clever talking; to bluff.",amharic:"ዘዴ ተጠቅሞ ማሳካት",example:"He managed to blag his way into the VIP section just by looking confident.",origin:"uk"},
{id:93,word:"Nick",meaning:"To steal something small; also a prison or police station.",amharic:"ለቅቆ ማውጣት / መስረቅ",example:"Who nicked my pen? I just put it down on the desk a second ago.",origin:"uk"},
{id:94,word:"Graft",meaning:"Hard work, effort; to work hard.",amharic:"ጠንክሮ መሥራት",example:"Success doesn't come without serious graft — you have to put in the hours consistently.",origin:"uk"},
{id:95,word:"Mug",meaning:"A foolish or gullible person who is easily tricked.",amharic:"ሞኝ / ቀላሉ",example:"Don't be such a mug — anyone could see that offer was too good to be true.",origin:"uk"},
{id:96,word:"Fit",meaning:"Physically attractive (British usage, not related to fitness).",amharic:"ቆንጆ / ማራኪ",example:"Did you see the new colleague? Absolutely fit — the whole office noticed.",origin:"uk"},
{id:97,word:"Sound",meaning:"Good, reliable, or trustworthy; can also mean okay or alright.",amharic:"ጥሩ / አስተማማኝ",example:"He's a sound lad — always shows up on time and never lets you down.",origin:"uk"},
{id:98,word:"Proper",meaning:"Used as an intensifier meaning 'very', 'really', or 'genuinely' — very British.",amharic:"በጣም / ትክክለኛ",example:"That curry last night was proper good — the best I've had since visiting India.",origin:"uk"},
{id:99,word:"Fancy",meaning:"To like or be attracted to someone; to want or desire something.",amharic:"ፍቅር ሆኖ / ማፈቅ",example:"I think she fancies you — she keeps finding excuses to come over to your desk.",origin:"uk"},
{id:100,word:"Peckish",meaning:"Slightly hungry; wanting a small snack.",amharic:"ትንሽ ሲርቦ",example:"I'm feeling a bit peckish — shall we find a cafe and grab a sandwich?",origin:"uk"},
{id:101,word:"Whinge",meaning:"To complain persistently and in an irritating way; to whine.",amharic:"ማጒረምረም / ዘወትር ማጠናለቅ",example:"Stop whinging about the weather — either get an umbrella or stay indoors.",origin:"uk"},
{id:102,word:"Innit",meaning:"Shortened 'isn't it?' — used broadly to seek agreement or affirmation.",amharic:"አይደል? / እርግጠኛ አይደህ",example:"That film was brilliant, innit? One of the best things I've seen this year.",origin:"uk"},
{id:103,word:"Blimey",meaning:"An exclamation of shock, surprise, or dismay.",amharic:"ሆ! / አይ! (ድንጋጤ)",example:"Blimey, I didn't expect to see you here — this is a complete coincidence!",origin:"uk"},
{id:104,word:"Ace",meaning:"Excellent, wonderful, or fantastic — very popular in British slang.",amharic:"ምርጥ / ድንቅ",example:"That was an absolutely ace performance — the audience gave a ten-minute standing ovation.",origin:"uk"},
{id:105,word:"Lush",meaning:"Lovely, attractive, or very pleasing; can describe food, people, or places.",amharic:"ቆንጆ / ደስ የሚያሰኝ",example:"These strawberries are absolutely lush — where did you find them so perfectly ripe?",origin:"uk"},
// More Gen-Z / Internet
{id:106,word:"No printer",meaning:"I can't lie; genuinely; telling the absolute truth with no exaggeration.",amharic:"ቅጂ ዘሩ / እውነቱን",example:"No printer, that was the most emotional concert I have ever attended in my life.",origin:"genz"},
{id:107,word:"Ate that",meaning:"Did something excellently; performed or executed perfectly.",amharic:"ዋና ዋና ነጥቦቹን ሰበሰበ",example:"She came on stage in that outfit and completely ate — no notes whatsoever.",origin:"genz"},
{id:108,word:"W",meaning:"A win; something positive or a victory — opposite of L (loss).",amharic:"ድል / ጥሩ ነው",example:"Getting promoted after just six months is a massive W — celebrate yourself!",origin:"genz"},
{id:109,word:"L",meaning:"A loss or failure — a negative outcome, opposite of W.",amharic:"ሽንፈት / ውድቀት",example:"Studying all night and still failing the exam? That is a brutal L.",origin:"genz"},
{id:110,word:"Ratio",meaning:"When a reply gets more likes than the original post — meaning most people disagree.",amharic:"ምላሽ ይበልጣል (አለመስማማት ምልክት)",example:"His tweet was so wrong that the ratio was immediate — everyone disagreed strongly.",origin:"internet"},
{id:111,word:"Sending me",meaning:"Something is making you laugh so hard you feel metaphorically sent away.",amharic:"እያስቃኝ ነው",example:"That meme is absolutely sending me — I've watched it 20 times and still cry laughing.",origin:"genz"},
{id:112,word:"Chefs kiss",meaning:"Something is perfect, excellent, or exactly right — gesture of approval.",amharic:"ፍጹም / አስደናቂ",example:"The combination of flavors in this dish is chef's kiss — absolute perfection.",origin:"internet"},
{id:113,word:"Pick me",meaning:"Someone who seeks approval by acting differently to seem superior to others.",amharic:"ራሴን ምረጡ / ድምጽ የሚሻ",example:"She always puts down other women to impress guys — classic pick me behavior.",origin:"genz"},
{id:114,word:"Beige flag",meaning:"A neutral, slightly odd habit that is neither a red flag nor a green flag.",amharic:"ሊስፈላጌ ያለ ትንሽ ልዩ ባሕርይ",example:"He organizes his wardrobe by color — weird beige flag but honestly kind of cute.",origin:"genz"},
{id:115,word:"Hot girl summer",meaning:"A period of confident, carefree enjoyment and self-love, usually in summer.",amharic:"ራስን ወዶ ደስ ማለት",example:"She booked three trips abroad, joined a book club, and had the hottest girl summer ever.",origin:"genz"},
{id:116,word:"Side quest",meaning:"A secondary activity or goal that is not your main focus but adds to your story.",amharic:"ሌላ ተግዳሮት / ሌላ ሥራ",example:"Learning pottery was just a side quest that turned into a genuinely profitable small business.",origin:"genz"},
{id:117,word:"Romanticize",meaning:"To make something seem more special, beautiful, or meaningful than it is.",amharic:"ሮማንቲክ አድርጎ ማሰብ",example:"She romanticizes every new city she visits, imagining living there forever.",origin:"genz"},
{id:118,word:"Gatekeep",meaning:"To keep information, places, or opportunities exclusive and not share widely.",amharic:"ሳይጋሩ ሚስጢር ያዙ",example:"Stop gatekeeping that restaurant — it's not your personal secret.",origin:"internet"},
{id:119,word:"Gaslight",meaning:"To manipulate someone into questioning their own memory or perception of reality.",amharic:"ሰዎች ሐሳባቸውን እንዲጠራጠሩ ማድረግ",example:"He kept denying things she clearly remembered — she realized he had been gaslighting her.",origin:"internet"},
{id:120,word:"Girlboss",meaning:"An ambitious, successful woman who runs her own business or leads boldly.",amharic:"ስኬታማ ሴት ወሳኝ",example:"She quit her corporate job at 28, launched her own brand, and became a total girlboss.",origin:"internet"},
// More US
{id:121,word:"Crash",meaning:"To go to sleep suddenly; to stay somewhere uninvited; to attend uninvited.",amharic:"ቁርጥ ብሎ መተኛት",example:"I'm so tired I'm going to crash the moment my head hits the pillow tonight.",origin:"us"},
{id:122,word:"Hang",meaning:"To spend time socially with someone — 'let's hang'.",amharic:"አብሮ ጊዜ ማሳለፍ",example:"We should hang this weekend — I feel like we haven't talked properly in months.",origin:"us"},
{id:123,word:"Bruh",meaning:"An exclamation of disbelief, frustration, or surprise — evolved from 'bro'.",amharic:"አቤት! / ወዳጄ!",example:"Bruh, you seriously waited until the night before to start that 10-page assignment?",origin:"us"},
{id:124,word:"Squad",meaning:"A close group of friends who do things together.",amharic:"ቡድን / ጓደኞቹ",example:"My squad and I go on an annual trip together — this year we're doing Thailand.",origin:"us"},
{id:125,word:"Ghost",meaning:"To suddenly stop all contact with someone without explanation.",amharic:"ሳይነግሩ ለቆ መሄድ",example:"We were texting every day for a month and then she just ghosted me completely.",origin:"internet"},
{id:126,word:"Lowdown",meaning:"The full and honest information about something — 'give me the lowdown'.",amharic:"ሙሉ ዝርዝር መረጃ",example:"Give me the lowdown on what happened at the meeting — I missed everything.",origin:"us"},
{id:127,word:"Catch feelings",meaning:"To unexpectedly develop romantic feelings for someone.",amharic:"ፍቅር ሆኖ መሰማት",example:"We were just supposed to be friends but I think I'm starting to catch feelings.",origin:"us"},
{id:128,word:"Level up",meaning:"To improve, advance, or move to a better position in life or skill.",amharic:"ደረጃ ወደ ላይ ማሳደግ",example:"She decided to level up by enrolling in an MBA program and changing her entire career.",origin:"internet"},
{id:129,word:"Keep it 100",meaning:"To be completely honest, authentic, and genuine.",amharic:"ሙሉ ለሙሉ ቀጥ ያለ ሁን",example:"If you want real feedback, I'll keep it 100 — that script needs serious rewriting.",origin:"us"},
{id:130,word:"Vibe check",meaning:"Assessing whether someone or something has good energy or compatible feelings.",amharic:"ስሜቱን ማረጋገጥ",example:"Let's do a vibe check before we invite him to join the group — does everyone feel comfortable?",origin:"genz"},
{id:131,word:"Come through",meaning:"To arrive; to deliver on a promise; to pull through in a critical moment.",amharic:"ደረሰ / ቃሉን ጠበቀ",example:"I wasn't sure she could do it, but she came through with the most brilliant solution.",origin:"us"},
{id:132,word:"Dip",meaning:"To leave quickly and quietly; to exit.",amharic:"ፈጠን ብሎ መሄድ",example:"The party was getting dull so we decided to dip around midnight and find somewhere else.",origin:"us"},
{id:133,word:"Lit fam",meaning:"Very good among friends — a combination of lit (great) and fam (family/friends).",amharic:"ምርጥ ጓደኞች",example:"The barbecue was lit fam — everyone brought something and the vibe was perfect.",origin:"us"},
{id:134,word:"No worries",meaning:"Used to say something is fine or to express no concern about a mistake.",amharic:"ምንም አይደል / ቁዘማ የለ",example:"Sorry I'm five minutes late! — No worries at all, we haven't even ordered yet.",origin:"us"},
{id:135,word:"For real",meaning:"Seriously; genuinely; used to confirm that something is true.",amharic:"እውነቱን / ከልቤ",example:"For real, that concert last night was one of the best nights of my entire life.",origin:"us"},
{id:136,word:"Ditch",meaning:"To abandon or leave someone suddenly, especially when you had plans.",amharic:"ጥሎ ሄደ",example:"She ditched her original career plans to pursue her passion for environmental science.",origin:"us"},
{id:137,word:"Snitch",meaning:"Someone who tells authorities about another person's wrongdoing.",amharic:"ሰጪ / ሚሸጥ",example:"Nobody in the neighborhood was willing to cooperate — everyone feared being called a snitch.",origin:"us"},
{id:138,word:"Mad",meaning:"Used as an intensifier meaning 'very' or 'extremely' — New York slang.",amharic:"በጣም / ከፍ ብሎ",example:"That new restaurant downtown is mad good — every single dish was incredible.",origin:"us"},
{id:139,word:"Word",meaning:"I agree; that's true; confirmation of what was just said.",amharic:"እሺ / ልክ ነው",example:"She works twice as hard as everyone else and gets paid half as much — word.",origin:"us"},
{id:140,word:"Peeps",meaning:"People; friends; one's social circle.",amharic:"ሰዎቹ / ጓደኞቹ",example:"I'll ask my peeps if anyone is free this weekend to help move my furniture.",origin:"us"},
// Internet/universal
{id:141,word:"IYKYK",meaning:"If You Know You Know — an exclusive reference that only certain people understand.",amharic:"የሚያውቅ ያውቃል",example:"That café near the old bridge is the best-kept secret in this city — IYKYK.",origin:"internet"},
{id:142,word:"Hits",meaning:"Successful songs, products, or moments — or simply something that lands perfectly.",amharic:"ስኬት / ሥራው ሰርቷል",example:"Everything she releases hits — her creative instincts have never once failed her.",origin:"internet"},
{id:143,word:"Finesse",meaning:"To achieve something through skill, smoothness, and clever maneuvering.",amharic:"በዘዴ ማሳካት",example:"She finessed her way into the sold-out show by knowing someone on the guest list.",origin:"us"},
{id:144,word:"Pull",meaning:"The ability to attract romantic partners; also to bring someone in.",amharic:"ሰዎችን መሳብ",example:"He walked in and immediately pulled three different people's numbers in one evening.",origin:"us"},
{id:145,word:"Plug",meaning:"A connection or supplier who can get you something exclusive or hard to find.",amharic:"ጠቃሚ ግንኙነት / ምንጭ",example:"He's my plug for tickets to sold-out events — always comes through somehow.",origin:"us"},
{id:146,word:"Clapped",meaning:"Unattractive or of very poor quality (British); also means exhausted (US).",amharic:"ያልደነቀ / ቆንጆ ያልሆነ",example:"After three flights and 30 hours of travel, I feel absolutely clapped.",origin:"uk"},
{id:147,word:"Suss",meaning:"Suspicious or questionable; also to figure something out.",amharic:"አጠራጣሪ / ያጠራጠረ",example:"Something about that deal feels completely suss — let's not rush into anything.",origin:"uk"},
{id:148,word:"Bodge",meaning:"To do something in a quick, careless, makeshift way.",amharic:"ዘፈቀደ ሥራ / ተሰናሳና",example:"He completely bodged the repair and now the situation is worse than before.",origin:"uk"},
{id:149,word:"Send it",meaning:"To go for something boldly without hesitation; to commit fully to an action.",amharic:"ሳትፈራ ሂድ",example:"The ramp looked scary but she sent it anyway and landed perfectly.",origin:"us"},
{id:150,word:"Built different",meaning:"To be fundamentally superior or uniquely capable in a way others cannot match.",amharic:"ከሌሎች ተለይቶ የተፈጠረ",example:"She trained every single day for five years with no days off — she's genuinely built different.",origin:"genz"},
// Additional entries to reach 200+
{id:151,word:"Flex on",meaning:"To show off or demonstrate superiority over someone else.",amharic:"ጉራ ማድረግ ሌላ ሰው ፊት",example:"She worked five years to get that promotion just so she could flex on her doubters.",origin:"us"},
{id:152,word:"No filter",meaning:"Saying exactly what you think without censoring yourself.",amharic:"ሳትሸፍን ቀጥ ብሎ",example:"Ask her what she thinks — she has absolutely no filter and will tell you the truth.",origin:"internet"},
{id:153,word:"Big mood",meaning:"Something that perfectly resonates with or captures your current feeling.",amharic:"ሁናቴን ይወክላል",example:"Wanting to cancel all plans and stay home reading? Big mood — that's every Friday for me.",origin:"genz"},
{id:154,word:"Slay the house down",meaning:"To perform or appear so impressively that you dominate the entire situation.",amharic:"ሙሉ ለሙሉ ሁሉን ቀሪ ትቷ",example:"She came on stage in that gown and slayed the house down — nobody could look away.",origin:"genz"},
{id:155,word:"Not it",meaning:"Expressing refusal or that something is absolutely not your responsibility.",amharic:"እኔ አይደለሁ / ለእኔ አይደለም",example:"Someone needs to tell him the project failed — not it, absolutely not going anywhere near that.",origin:"genz"},
{id:156,word:"Dead",meaning:"So funny or shocking that it metaphorically 'kills' you — 'I'm dead'.",amharic:"ሞቻለሁ (እያስቃኝ ነው)",example:"She told the story so dramatically that I was completely dead — couldn't breathe from laughing.",origin:"us"},
{id:157,word:"Pressed",meaning:"Unnecessarily bothered, upset, or worked up about something relatively minor.",amharic:"ቅር ብሎ / ለምን ሆነ ብሎ",example:"Why is he so pressed about a comment that wasn't even directed at him?",origin:"us"},
{id:158,word:"Sus",meaning:"Suspicious; acting strangely or seeming to hide something.",amharic:"አጠራጣሪ / ሚስጢር ያለ",example:"He disappeared for three hours and won't say where he went — that is extremely sus.",origin:"internet"},
{id:159,word:"Big brain",meaning:"An extremely clever or intelligent idea or decision.",amharic:"ብልህ ሐሳብ / ጥልቅ አስተሳሰብ",example:"Studying the exam questions from previous years? That was a big brain move.",origin:"internet"},
{id:160,word:"Catch hands",meaning:"To get into a physical fight; to confront someone physically.",amharic:"ምቱን ማግኘት / ለምት ዝግጁ ሆን",example:"Keep talking disrespectfully and you're going to catch hands — I'm giving you one warning.",origin:"us"},
{id:161,word:"Living rent free",meaning:"An idea, person, or song occupying your thoughts without you wanting it.",amharic:"ሳይፈቀድ ሐሳብህ ቤት ያለ",example:"That song from three years ago is still living completely rent free in my head.",origin:"genz"},
{id:162,word:"Opp",meaning:"An opponent, enemy, or rival — short for 'opposition'.",amharic:"ተቃዋሚ / ጠላት",example:"Watch what you say around certain people — not everyone you know is really your friend.",origin:"us"},
{id:163,word:"Caught in 4K",meaning:"Caught doing something wrong with undeniable proof or evidence.",amharic:"ምልክት ወይም ማስረጃ ይዞ ተያዘ",example:"He denied taking the money but they had him caught in 4K on camera.",origin:"internet"},
{id:164,word:"Understood",meaning:"An acknowledgment that you fully get the situation or will do what's asked.",amharic:"ገብቶኛል / ተረደሁ",example:"You need the report by 9 AM? Understood — it will be on your desk at eight.",origin:"genz"},
{id:165,word:"The audacity",meaning:"Expressing shocked disbelief at someone's boldness or nerve.",amharic:"ድፍረቱ / ዝናቱ",example:"She didn't do any work on the project and then asked for the most credit — the audacity!",origin:"us"},
{id:166,word:"Moment",meaning:"Experiencing a particularly good or noteworthy time — 'having a moment'.",amharic:"ወቅቱ / ጊዜ",example:"This artist is really having a moment — three hits in a row and world tours already booked.",origin:"genz"},
{id:167,word:"Hyped",meaning:"Extremely excited and enthusiastic, often after being promoted or built up.",amharic:"ጉጉ ሆኖ / ደስ ብሎ",example:"Everyone was hyped for the film, but the actual release was a disappointment.",origin:"us"},
{id:168,word:"Clout chasing",meaning:"Doing things purely to gain social media fame or attention from others.",amharic:"ዝና ፍለጋ",example:"Half of those charity posts are just clout chasing — true giving should be private.",origin:"internet"},
{id:169,word:"No shame",meaning:"Acting boldly without caring what others think — often positively.",amharic:"ሀፍረት ሳይሰማ",example:"I ate the entire pizza by myself with no shame whatsoever and slept like a baby.",origin:"us"},
{id:170,word:"Catch a vibe",meaning:"To connect with someone emotionally or atmospherically; to sense energy.",amharic:"ከሰው ጋር ስሜት መቀባበል",example:"We caught a vibe almost immediately — the conversation just flowed naturally from the start.",origin:"us"},
{id:171,word:"Run it back",meaning:"To replay or repeat something; to go back to the start.",amharic:"ደጋግሞ ማካሄድ / ወደ ኋላ ማዞር",example:"That song is so good — can you run it back from the beginning one more time?",origin:"us"},
{id:172,word:"Real talk",meaning:"Being completely honest and sincere — dropping all pretense.",amharic:"እውነቱን ለመናገር",example:"Real talk, I think you need to reconsider this entire career path before it's too late.",origin:"us"},
{id:173,word:"Clutch",meaning:"Performing exceptionally well under pressure at the most crucial moment.",amharic:"ወሳኝ ጊዜ ጥሩ ሥራ",example:"She scored the winning goal in the final seconds — that was the most clutch moment I've seen.",origin:"us"},
{id:174,word:"On point",meaning:"Exactly right, perfect, or precisely accurate.",amharic:"ትክክለኛ / ፍጹም",example:"Everything about that event was on point — the venue, the food, the entertainment, everything.",origin:"us"},
{id:175,word:"All that",meaning:"Thinking you're better than you really are; full of yourself.",amharic:"ራሱን ሸቅሷሸቅቭ / ትዕቢተኛ",example:"He acts like he's all that just because he got a promotion — humble yourself.",origin:"us"},
{id:176,word:"Hundo P",meaning:"100 percent; completely sure or certain.",amharic:"መቶ በመቶ / ሙሉ ለሙሉ",example:"Are you coming to the party? Hundo P — I wouldn't miss it for anything.",origin:"us"},
{id:177,word:"Stan culture",meaning:"The phenomenon of extremely devoted fan communities online.",amharic:"ሞቅ ያለ ደጋፊ ባህል",example:"Stan culture can be positive when fans support artists but toxic when they attack critics.",origin:"internet"},
{id:178,word:"Spicy",meaning:"Bold, edgy, or controversial — containing strong opinions or content.",amharic:"ሞቅ ያለ / ደፋር",example:"That is a very spicy opinion for a work meeting — maybe save it for after hours.",origin:"us"},
{id:179,word:"Go off",meaning:"To speak passionately and at length without holding back.",amharic:"ቁጣ ወይም ፍቅር ሙሉ ሙሉ ማሳየት",example:"She went completely off about the unfairness of the situation and everyone was speechless.",origin:"us"},
{id:180,word:"No thoughts head empty",meaning:"A humorous way to say you aren't thinking about anything in particular.",amharic:"ምንም አሰብ የሌለ ዘና ያለ ሁኔታ",example:"It's Saturday morning and I am in bed with no thoughts, head empty — perfect.",origin:"internet"},
{id:181,word:"Pressed for",meaning:"To be lacking or short of something, usually time.",amharic:"ጊዜ አጥሮ / አጥሮ",example:"I'm really pressed for time this week — can we reschedule to next Monday?",origin:"us"},
{id:182,word:"On a roll",meaning:"Experiencing a series of successes; performing consistently well.",amharic:"ዘወትር ስኬት / ሃሳቡ ሁሉ ሰርቷል",example:"She's been on a roll lately — every project she touches turns into something extraordinary.",origin:"us"},
{id:183,word:"Clapback",meaning:"A sharp, clever verbal response to a criticism or insult.",amharic:"ቀጥ ያለ ምላሽ",example:"His clapback to the critic's review was so devastatingly witty that everyone applauded.",origin:"us"},
{id:184,word:"Triggering",meaning:"Causing an emotional or negative reaction, often referring to past trauma.",amharic:"ስሜት የሚቀሰቅስ / ቅር የሚያሰኝ",example:"That news story was deeply triggering for survivors of that type of trauma.",origin:"internet"},
{id:185,word:"Based",meaning:"Holding confident, authentic opinions without caring about others' judgment.",amharic:"ድፍረትና ቀጥ ያለ አቋም",example:"He refused to follow the trend and wore exactly what he wanted — that's based behavior.",origin:"internet"},
{id:186,word:"Cringe",meaning:"Embarrassingly awkward or uncomfortable to watch.",amharic:"አሳፋሪ / ያሸበረ",example:"Watching videos of yourself from five years ago is genuinely cringe but also hilarious.",origin:"internet"},
{id:187,word:"Mid",meaning:"Average, mediocre, or not particularly impressive — not good or bad.",amharic:"መካከለኛ / ምንም ያልሆነ",example:"Everyone hyped up that movie but honestly it was mid — I expected so much more.",origin:"genz"},
{id:188,word:"Lowkey slaps",meaning:"Something that is quietly or unexpectedly really good.",amharic:"ጸጥ ብሎ ጥሩ",example:"That background music in the café lowkey slaps — who is the artist?",origin:"genz"},
{id:189,word:"Say less",meaning:"I understand completely — no need for more explanation.",amharic:"ተረዳሁ / ሌላ አያስፈልጋ",example:"You need help moving on Saturday? Say less — I'll be there at 8 AM.",origin:"us"},
{id:190,word:"Do the most",meaning:"To try too hard or be overly dramatic or excessive in behavior.",amharic:"ከሚያስፈልገው ይበልጥ ማድረግ",example:"She always does the most — five-minute task turned into a three-hour production.",origin:"us"},
{id:191,word:"Mood board",meaning:"A collection of images, text, and ideas representing an aesthetic vision.",amharic:"ስዕላዊ ሐሳብ ስብስብ",example:"She created a detailed mood board for her dream apartment before buying a single item.",origin:"internet"},
{id:192,word:"Aesthetic",meaning:"Having or relating to a particular pleasing visual style or atmosphere.",amharic:"ዓይነ-ደምቅ / ቁንጅና አቅጣጫ",example:"Her whole social media page has a perfect dark academia aesthetic — it's so cohesive.",origin:"internet"},
{id:193,word:"Ngl",meaning:"Not gonna lie — used before being honest or sharing an unpopular opinion.",amharic:"ውሸት ሳልናገር",example:"Ngl, I actually kind of liked that movie everyone else said was terrible.",origin:"internet"},
{id:194,word:"Tbh",meaning:"To be honest — used before sharing a sincere or candid opinion.",amharic:"솔직히 말해서 / ሐቀኛ ሆኜ",example:"Tbh, I think you should have spoken up much sooner — it would have changed everything.",origin:"internet"},
{id:195,word:"Idk",meaning:"I don't know — expressing uncertainty or lack of information.",amharic:"አላውቅም",example:"Idk what to do about this situation anymore — I've tried everything and nothing works.",origin:"internet"},
{id:196,word:"Lowkey obsessed",meaning:"Quietly and somewhat secretly very interested in or attracted to something.",amharic:"ሳይናተ ፍቅር ያለ",example:"I'm lowkey obsessed with that true crime podcast — I've listened to every episode twice.",origin:"genz"},
{id:197,word:"It's not giving",meaning:"Something is failing to deliver the expected vibe, energy, or impression.",amharic:"የሚፈለገው ስሜት አይሰጥም",example:"You changed the title but the content is still the same — it's just not giving.",origin:"genz"},
{id:198,word:"Oof",meaning:"An expression of discomfort, sympathy, or pain at someone's bad situation.",amharic:"ኧረ! / አዝናለሁ",example:"She got rejected from every university she applied to? Oof, that is genuinely devastating.",origin:"internet"},
{id:199,word:"Fam",meaning:"Family; also used broadly for close friends — a term of affection.",amharic:"ቤተሰብ / የቤተሰብ ጓደኛ",example:"These people have been my fam since we were in school — we go way back.",origin:"us"},
{id:200,word:"Caught feelings",meaning:"Unexpectedly developing romantic feelings when you didn't intend to.",amharic:"ሳይፈልጉ ፍቅር ሆኖ",example:"We were just supposed to be study partners but I think I've caught serious feelings.",origin:"us"},
{id:201,word:"Swipe right",meaning:"To show romantic interest in someone (from dating apps like Tinder).",amharic:"ፍቅር ማሳወቅ / አዎ ማለት",example:"Millions of people swipe right daily hoping to find genuine connection online.",origin:"internet"},
{id:202,word:"Unfollowed",meaning:"Removed someone from your social media feed; sometimes used metaphorically.",amharic:"ቀጠናው ሰረዝ",example:"After the way he behaved, I unfollowed him in real life too — not just on Instagram.",origin:"internet"},
{id:203,word:"Zoning out",meaning:"To stop paying attention and drift into your own thoughts.",amharic:"ሐሳብ ጠፍቶ / ትኩረት አጥቶ",example:"I kept zoning out during the lecture — I need more sleep if I'm going to focus properly.",origin:"us"}
];

