// 6. WRITING PROMPTS (30 prompts)
// ─────────────────────────────────────────────
const WRITING_PROMPTS = [
  {id:1,level:"Intermediate",prompt:"Describe a person who has had a significant positive impact on your life. Who are they, what did they do, and how did they change the way you think or live?",tips:["Use descriptive language to bring the person to life","Include specific memories or moments, not just general statements","Explain the lasting impact using the present perfect tense"]},
  {id:2,level:"Intermediate",prompt:"Do you think technology has made modern life better or worse overall? Give your opinion and support it with at least three specific reasons and examples.",tips:["State your opinion clearly in the first sentence","Use discourse markers: furthermore, however, on the other hand","Include both sides before concluding with your position"]},
  {id:3,level:"Advanced",prompt:"'The greatest barrier to success is not a lack of talent, but a fear of failure.' Do you agree or disagree with this statement? Write a structured argument.",tips:["Use a formal academic tone throughout","Include a counterargument and then refute it","End with a nuanced conclusion, not a simple yes or no"]},
  {id:4,level:"Intermediate",prompt:"Describe the most challenging experience you have ever faced. What happened, how did you respond, and what did you ultimately learn from it?",tips:["Use past simple and past continuous for storytelling","Include your emotional response, not just events","Reflect on the lesson learned in your conclusion"]},
  {id:5,level:"Advanced",prompt:"To what extent should governments limit individuals' freedom for the sake of public safety? Discuss this ethical tension with reference to specific examples.",tips:["Define key terms: freedom, public safety, government responsibility","Use hedging language to show nuance","Consider at least two perspectives before presenting your own"]},
  {id:6,level:"Intermediate",prompt:"Write about a significant change you would like to make in your life. What would you change, why, and what specific steps would you take to achieve it?",tips:["Use 'would' and 'going to' appropriately for future plans","Be specific — avoid vague language","Connect each step to the next with linking words"]},
  {id:7,level:"Advanced",prompt:"'Social media has done more harm than good to society.' Critically evaluate this claim, drawing on specific evidence and examples to support your argument.",tips:["Use present perfect to reference research and trends","Include statistics or examples to make it concrete","Acknowledge complexity — avoid an oversimplified conclusion"]},
  {id:8,level:"Intermediate",prompt:"Describe your ideal working environment. What conditions help you focus and perform best, and how do those conditions reflect your personality?",tips:["Use sensory details to make your description vivid","Explain the connection between environment and performance","Use relative clauses to add detail: 'a place where...'"]},
  {id:9,level:"Advanced",prompt:"Discuss the role of education in reducing social inequality. Is education genuinely a great equalizer, or does it sometimes reinforce existing advantages?",tips:["Introduce the paradox of education's role clearly","Use academic phrases: 'it can be argued that', 'research suggests'","Propose what reforms might address the limitations you identify"]},
  {id:10,level:"Intermediate",prompt:"Write about a skill you are currently trying to develop. Why is it important to you, what challenges have you faced, and how are you overcoming them?",tips:["Use present continuous and present perfect appropriately","Include specific examples of challenges, not just general statements","Show growth by comparing past and present states"]},
  {id:11,level:"Advanced",prompt:"'Reading literary fiction is one of the most powerful tools for developing empathy and social understanding.' Evaluate this claim critically.",tips:["Define 'literary fiction' and 'empathy' at the start","Reference relevant psychological research if possible","Discuss limitations and alternative views fairly"]},
  {id:12,level:"Intermediate",prompt:"If you could live in any city in the world for one year, where would you choose and why? What would you hope to experience or achieve during that year?",tips:["Use second conditional: 'If I lived in X, I would...'","Be specific about place, activities, and goals","Include one challenge you might face and how you'd handle it"]},
  {id:13,level:"Advanced",prompt:"Examine the relationship between economic growth and environmental sustainability. Is genuine balance achievable, or must one be sacrificed for the other?",tips:["Present the conflict clearly in the introduction","Use passive voice where appropriate for academic tone","Suggest a nuanced position rather than a binary one"]},
  {id:14,level:"Intermediate",prompt:"Write a letter to your younger self. What advice would you give? What do you wish you had known then that you know now?",tips:["Address your younger self directly using 'you'","Use a warm but honest tone — include difficult truths","Move from personal regrets to universal lessons"]},
  {id:15,level:"Advanced",prompt:"'Artificial intelligence poses a greater threat to humanity than any technology that has come before it.' Critically assess this claim with specific reference to current developments.",tips:["Distinguish between short-term and long-term risks","Consider economic, social, and ethical dimensions","Avoid alarmist or dismissive conclusions — aim for balance"]},
  {id:16,level:"Intermediate",prompt:"Describe a tradition or cultural practice that is important to you. What does it involve, why does it matter, and what would be lost if it disappeared?",tips:["Bring the practice to life through specific sensory details","Explain the cultural and personal significance","Use present simple for habitual practices"]},
  {id:17,level:"Advanced",prompt:"To what extent does language shape the way we think and perceive reality? Discuss this idea with reference to specific languages or examples.",tips:["Reference the Sapir-Whorf hypothesis if possible","Give concrete examples: colour words, gendered nouns, etc.","Consider both strong and weak versions of the claim"]},
  {id:18,level:"Intermediate",prompt:"Some people believe that persistence matters more than natural talent. Write an essay arguing whether you agree, using examples from your own life or from people you admire.",tips:["State your thesis clearly in the introduction","Use real examples — abstract arguments are less convincing","Acknowledge the role of talent while still arguing for persistence"]},
  {id:19,level:"Advanced",prompt:"Discuss how social media has changed the nature of activism and political engagement. Has it made civic participation more or less effective?",tips:["Distinguish between online activism and real-world impact","Use evidence: Arab Spring, #MeToo, climate activism","Avoid ideological bias — consider multiple perspectives"],},
  {id:20,level:"Intermediate",prompt:"Write about a book, film, or piece of music that deeply affected you. What was it about, why did it resonate, and what did it make you think or feel?",tips:["Engage the reader with a vivid description of the work","Explore why it affected you specifically, not just generally","Connect the work to a broader theme or truth about life"]},
  {id:21,level:"Advanced",prompt:"'The pursuit of happiness has made modern people more anxious and less fulfilled than ever before.' Critically discuss this claim.",tips:["Explore the psychology of happiness and hedonic adaptation","Reference both positive psychology and its critics","Propose what a healthier relationship with happiness might look like"]},
  {id:22,level:"Intermediate",prompt:"Describe a time when you changed your mind about something important. What did you believe before? What new information or experience changed your perspective?",tips:["Show genuine intellectual humility — this makes strong writing","Trace the journey of your thinking step by step","Conclude with what you now believe and why"]},
  {id:23,level:"Advanced",prompt:"Examine the claim that 'the richest countries have a moral obligation to provide significant financial assistance to poorer nations.' Do you agree?",tips:["Define 'moral obligation' and whether it applies internationally","Consider both historical injustices and current inequalities","Balance idealism with practical considerations"]},
  {id:24,level:"Intermediate",prompt:"What do you think is the most important quality a person can have? Define the quality, explain why it matters most, and give examples of people who embody it.",tips:["Define the quality carefully at the start","Use real or historical examples to make it concrete","Acknowledge other important qualities before explaining why yours is paramount"]},
  {id:25,level:"Advanced",prompt:"'Global citizenship is a more meaningful identity than national identity in the twenty-first century.' Do you agree or disagree? Construct a nuanced argument.",tips:["Define both 'global citizenship' and 'national identity'","Consider when each identity is most salient and meaningful","Avoid a simplistic conclusion — the tension is real and complex"]},
  {id:26,level:"Intermediate",prompt:"Describe a moment in your life when you overcame fear to do something important. What was the fear, what did you do, and what did overcoming it teach you?",tips:["Build the reader's understanding of the fear before the action","Use vivid sensory language to create immediacy","Reflect deeply on the lesson — this is the heart of the essay"]},
  {id:27,level:"Advanced",prompt:"How has the concept of privacy changed in the digital age? Is privacy still achievable or meaningful in a world of mass data collection?",tips:["Trace the historical evolution of privacy as a value","Address corporate data collection and government surveillance","Conclude with what privacy might realistically mean today"]},
  {id:28,level:"Intermediate",prompt:"Write about someone who inspires you from history. Who are they, what did they do, and why do you find their life meaningful or instructive?",tips:["Choose someone whose story genuinely moves you","Use past simple and past perfect to structure the narrative","Draw out the lesson for readers today — make it universal"]},
  {id:29,level:"Advanced",prompt:"'Climate change represents a unique moral challenge because those who suffer most are least responsible for causing it.' Discuss the ethical implications of this statement.",tips:["Frame this as an issue of global justice and responsibility","Discuss both individual and national levels of responsibility","Propose actionable and principled responses"],},
  {id:30,level:"Intermediate",prompt:"If you had the power to change one thing about the world, what would it be and why? How would the world be different, and what challenges might that change create?",tips:["Choose something you genuinely care about deeply","Think beyond the obvious — the most interesting essays are specific","Address unintended consequences — this shows sophistication"]},
];

